/** Actions provided by the plugin to trigger state updates. */
export const useColumnsSizesActions = {
  /**
   * Action fired if the visible columns changed to recreate the grid template if necessary.
   */
  visibleColumnsChanged: 'visibleColumnsChanged',

  /**
   * Action fired internally when a column was measured.
   */
  cellWidthMeasureDone: 'cellWidthMeasureDone',

  /**
   * Action fired internally when the row density changed.
   */
  rowDensityChanged: 'rowDensityChanged',

  /**
   * Action fired when starting to resize a column.
   */
  columnStartResizing: 'columnStartResizing',

  /**
   * Action fired when a column is done resizing.
   */
  columnDoneResizing: 'columnDoneResizing',

  /**
   * Action fired when the saved resized column widths need to be updated.
   */
  updateResizedColumnWidths: 'updateResizedColumnWidths',

  /**
   * Action fired when font families update.
   */
  fontsFamiliesUpdated: 'fontFamiliesUpdated',

  /**
   * Action fired when the rendered virtualized columns changed.
   */
  virtualColumnsChanged: 'virtualColumnsChanged',

  /**
   * Action fired when the sub rows depth changes and its column width needs to be adjusted.
   */
  subRowsDepthChanged: 'subRowsDepthChanged',
};
